/* ---- Instructions: the operand (imm) or address (scratch) in EA ---- */

/* A = A + EA + C, or A - EA - !C, with C, V into REG_CF, REG_OF and N, Z
 * into the host flags. As the JIT's ADC / SBC: the 8 bits at the top of a
 * word, with the carry in rippling through the low bits.
 */
static void
t2i_adc_sbc(struct util_buffer* p_buf, int is_sbc) {
  t2_shift(p_buf, k_t2_lsr, 1, BASE, REG_CF, 1);
  if (!is_sbc) {
    t2_dp_imm(p_buf, k_t2_op_orn, 0, T, k_t2_pc, 0xFF000000);
    t2_dp_reg(p_buf, k_t2_op_orr, 0, T, T, REG_A, k_t2_lsl, 24);
    t2_dp_reg(p_buf, k_t2_op_adc, 1, T, T, EA, k_t2_lsl, 24);
  } else {
    t2_shift(p_buf, k_t2_lsl, 0, T, REG_A, 24);
    t2_dp_reg(p_buf, k_t2_op_sbc, 1, T, T, EA, k_t2_lsl, 24);
  }
  t2_shift(p_buf, k_t2_lsr, 0, REG_A, T, 24);
  t2i_save_carry(p_buf);
  t2_mrs_apsr(p_buf, T);
  t2_ubfx(p_buf, REG_OF, T, 28, 1);
  t2i_nz(p_buf, REG_A);
}

void
asm_emit_instruction_ADC_imm_interp(struct util_buffer* p_buf) {
  t2i_mode_imm(p_buf);
  t2i_adc_sbc(p_buf, 0);
}

