void
asm_emit_instruction_JSR_scratch_interp(struct util_buffer* p_buf) {
  /* The target first: the pushes could overwrite the operand. */
  t2i_operand_ptr(p_buf);
  t2_ldrh(p_buf, REG_VALUE, T, 1);
  t2i_push_pc_plus_2(p_buf);
  t2_mov16(p_buf, PC, REG_VALUE);
}

