/* Standalone inturbo (-mode inturbo) isn't supported: these are only
 * referenced.
 */
uint32_t
asm_inturbo_enter(void* p_context,
                  void* p_start_address,
                  int64_t countdown,
                  void* p_mem_base) {
  (void) p_context;
  (void) p_start_address;
  (void) countdown;
  (void) p_mem_base;
  util_bail("thumb2: no standalone inturbo");
  return 0;
}

void
asm_inturbo_interp_trampoline(void) {
  assert(0);
}

void
asm_inturbo_interp_trampoline_ret(void) {
  assert(0);
}
